#!/usr/bin/env python3
"""Prepare hosting headers, retaining the single public-assets-only worker."""
from pathlib import Path
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else 'build/web').resolve()
if not (root / 'index.html').is_file() or not (root / 'spar_offline.js').is_file():
    raise SystemExit('Build the Flutter web app first, including spar_offline.js.')

# The bootstrap already registers spar_offline.js. A second worker at the
# same scope races registration and deletes the first worker's asset cache.
# Remove only files and markup generated by the previous helper.
index = (root / 'index.html').read_text()
index = index.replace('<script src="offline_register.js" defer></script>\n', '')
(root / 'index.html').write_text(index)
for name in ('sw.js', 'offline_register.js'):
    (root / name).unlink(missing_ok=True)

# Keep the worker's exact public asset allowlist. Never construct one by
# recursively collecting arbitrary files from a build directory.
headers = """/*
  Content-Security-Policy: default-src 'none'; base-uri 'self'; script-src 'self' 'wasm-unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self'; connect-src 'self'; worker-src 'self' blob:; manifest-src 'self'; object-src 'none'; frame-ancestors 'none'
  X-Content-Type-Options: nosniff
  Referrer-Policy: no-referrer
  Cross-Origin-Opener-Policy: same-origin
  Cross-Origin-Embedder-Policy: require-corp
  Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=(), usb=()
  Cache-Control: no-cache
"""
(root / '_headers').write_text(headers)
print('Prepared hosting headers; spar_offline.js remains the single static worker.')
